/* Runner's HIGH — UI and fixed-step race playback. */
'use strict';
const E=RH,$=id=>document.getElementById(id),STORE='runners-high-v1';
let p=E.fresh(),saveWarning='',race=null,paused=true,mode='training',distance=800,strategy='steady',playback=4,last=0,accum=0,lastSave=0,worker=null;
try{const raw=localStorage.getItem(STORE);if(raw){const parsed=JSON.parse(raw);if(E.validProgress(parsed)){p=parsed;p.settings=E.config(p.settings);if(p.activeRace?.racers?.length===8&&!p.activeRace.done){race=p.activeRace;mode=race.mode;distance=race.distance;strategy=race.strategy;}}else saveWarning='저장 데이터를 읽지 못했습니다. 새 선수로 시작합니다.';}}catch{saveWarning='자동 저장을 사용할 수 없습니다. 브라우저 저장 권한을 확인해 주세요.';}
const desc={stamina:'완주를 위한 총 에너지 용량',endurance:'후반 피로에 따른 속도 저하 억제',speed:'모든 구간의 기본 주행 속도',efficiency:'1m를 달릴 때의 체력 소모 감소',acceleration:'버튼 가속의 위력 · 사용 횟수',tactics:'추월 판단 · 앞 선수에게 막히는 시간 감소'};
const colors=['#d5fc57','#68c8ed','#f28c72','#b59cee','#efc278','#5ec9a6','#ea8eb6','#cad2d4'];
const fmt=s=>s===null||!Number.isFinite(s)?'DNF':`${Math.floor(s/60)}:${(s%60).toFixed(1).padStart(4,'0')}`;
function save(){try{localStorage.setItem(STORE,JSON.stringify(p));}catch{toast('저장 공간이 부족합니다. 진행 데이터 내보내기를 이용하세요.');}}
function toast(t){$('toast').textContent=t;$('toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.add('hidden'),4000);}
function render(){
$('app').innerHTML=`<header><div><h1>RUNNER’S <b>HIGH!!!</b></h1><span class="subbrand">EVERY LAP MAKES YOU.</span></div><div class="wallet"><span class="coin">C</span><strong id="coins"></strong><small>TRAIN. RACE. GROW.</small></div><button class="quiet" id="help">플레이 가이드</button></header>
<main class="shell"><div id="game"><div class="modebar"><div class="modes"><button id="training">01 훈련장</button><button id="stadium">02 스타디움 <span class="lock" id="lock"></span></button></div><span class="status" id="status"></span><button class="quiet" id="openLab">밸런스 실험실 ↗</button></div>${saveWarning?`<p class="notice">${saveWarning}</p>`:''}<div class="layout"><aside class="left panel"><div class="athlete"><div><span class="eyebrow">YOUR ATHLETE</span><div class="athlete-name"><strong>신인 러너<small>성장은 한 번의 선택부터.</small></strong></div></div><div class="bib">01</div></div><div class="panel-head"><h2>선수 성장</h2><span class="tag">MAX LV.100</span></div><div class="upgrades" id="upgrades"></div></aside>
<section class="center"><div class="panel"><div class="track-head"><div><span class="eyebrow" id="venue">TRAINING GROUND</span><h2 id="distanceTitle">800m</h2></div><div class="timer" id="timer">0:00.0</div></div><div class="canvas-wrap"><canvas id="track" aria-label="400미터 타원 트랙 위 8명의 선수 위치"></canvas><div class="track-caption"><strong id="trackLabel">MAKE YOUR MOVE.</strong><span id="trackSub">400m TRACK · 8 RUNNERS</span></div></div><div class="telemetry"><div><small>순위</small><b id="rank">— / 8</b></div><div><small>달린 거리</small><b id="meters">0 m</b></div><div><small>현재 속도</small><b id="speed">0.0 m/s</b></div></div><div class="race-controls"><div class="select-row"><label>경주 거리<select id="distance">${E.DISTANCES.map(d=>`<option value="${d}">${d.toLocaleString()}m · ${d/400}바퀴</option>`).join('')}</select></label><label>달리기 전략<select id="strategy">${Object.entries(E.STRATEGIES).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('')}</select></label></div><p class="readiness" id="readiness"></p><div class="energy-label"><span>체력 <strong id="energy"></strong></span><small id="fatigue">후반 피로 0%</small></div><div class="bar"><div id="energyBar"></div></div><div class="race-actions"><button class="primary" id="start">훈련 시작 →</button><button class="boost" id="boost">⚡ 가속 <span id="boostCount"></span></button></div><div class="playback"><span>재생 속도</span>${[1,2,4,8].map(n=>`<button data-play="${n}">${n}×</button>`).join('')}<button id="retire">기권</button></div><p class="fine">기록은 실제 경기 시간입니다. 가속 사용은 직접 선택하며, 탭을 떠나면 경기가 일시 정지됩니다.</p></div></div><div id="result"></div></section>
<aside class="right"><div class="panel"><div class="panel-head"><div><span class="eyebrow">LIVE RANKING</span><h2>트랙 위의 8명</h2></div></div><div id="standings"></div><p class="hint">훈련 상대는 내 수준과 비슷하거나 조금 더 강합니다. 공식경기는 고정된 상대 수준으로 진행됩니다.</p></div><div class="panel record-card"><span class="eyebrow">PERSONAL BEST</span><h3 id="pbTitle">훈련 · 800m</h3><strong id="pb">—</strong><p id="recordNote"></p><details><summary>최근 경기 기록</summary><div id="history"></div></details></div></aside></div></div><section class="lab" id="lab"></section></main><footer><span>RUNNER’S HIGH!!! / WEB PROTOTYPE 01</span><span>기기 내 자동 저장 · <button class="quiet" id="export">저장 내보내기</button></span></footer><div class="toast hidden" id="toast" role="status"></div><dialog id="guide"><h2>한 바퀴씩, 더 멀리.</h2><p>훈련을 5회 완주하면 공식 스타디움이 열립니다. 체력이 0이 되기 전에 결승선을 통과해야 보상을 받습니다.</p><ul><li>체력은 완주 능력, 지구력은 후반 속도 유지 능력입니다.</li><li>가속은 순간 체력을 사용합니다. 사용 후 10초간 재사용 대기시간이 있습니다.</li><li>가속력 레벨 1–10 / 11–20 / 21–40 / 41–60 / 61–80 / 81–100에서 각각 1 / 2 / 3 / 4 / 5 / 6회 사용할 수 있습니다.</li><li>훈련 보상은 완주 기본 보상만 지급됩니다. 공식경기는 완주 + 입상 + 기록 등급 + 잔여 체력 보너스가 합산됩니다.</li><li>첫 공식 입상 50–60분은 기본 4배속·800m 기록 우선 성장의 조정 목표입니다. 전략과 배속에 따라 달라집니다.</li><li>실험실의 테스트는 실제 선수의 재화와 기록을 바꾸지 않습니다.</li></ul><form method="dialog"><button class="primary">트랙으로 돌아가기</button></form></dialog>`;
$('help').onclick=()=>$('guide').showModal();$('openLab').onclick=openLab;
$('training').onclick=()=>chooseMode('training');$('stadium').onclick=()=>chooseMode('stadium');
$('distance').value=distance;$('strategy').value=strategy;
$('distance').onchange=e=>{distance=+e.target.value;update();};$('strategy').onchange=e=>{strategy=e.target.value;update();};
$('start').onclick=start;$('boost').onclick=()=>{if(race&&!paused&&E.boost(race)){save();updateLive();}};
$('retire').onclick=()=>{if(!race||race.done)return;if(!confirm('기권하면 이번 경주의 보상과 완주 횟수를 받을 수 없습니다. 기권할까요?'))return;race.racers[0].dnf=true;race.racers[0].finish=null;race.racers.forEach(a=>{if(a.finish===null)a.dnf=true;});race.done=true;finish();};
document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{playback=+b.dataset.play;update();});$('export').onclick=()=>download('runners-high-save.json',p);update();}
function chooseMode(m){if(race&&!race.done)return;if(m==='stadium'&&p.training<5){toast(`훈련 완주가 ${5-p.training}회 더 필요합니다.`);return;}mode=m;update();}
function start(){if(race&&!race.done){paused=!paused;update();return;}if(mode==='stadium'&&p.training<5)return;race=E.createRace({levels:p.levels,distance,strategy,mode,settings:p.settings,seed:crypto.getRandomValues(new Uint32Array(1))[0]});p.activeRace=race;paused=false;accum=0;$('result').innerHTML='';save();update();}
function finish(){paused=true;const rew=E.reward(race);E.settle(p,race);save();$('result').innerHTML=`<h2>${race.racers[0].dnf?'다음 도전은 더 멀리.':`${rew.rank}위 · ${fmt(race.racers[0].finish)}`}</h2><p>${race.racers[0].dnf?'체력이 소진되었거나 기권했습니다. 체력을 강화하거나 완주 우선 전략을 선택해 보세요.':`${rew.tier} · +${rew.total.toLocaleString()} 코인 획득`}</p><div class="reward-grid">${[['완주',rew.finish],['입상',rew.podium],['기록',rew.record],['잔여 체력',rew.reserve]].map(([n,v])=>`<div>${n}<b>+${v}</b></div>`).join('')}</div>`;$('result').className='result';update();}
function update(){const active=race&&!race.done;$('coins').textContent=p.coins.toLocaleString();$('training').classList.toggle('selected',mode==='training');$('stadium').classList.toggle('selected',mode==='stadium');$('lock').textContent=p.training<5?`잠김 ${p.training}/5`:'';$('status').textContent=`훈련 완주 ${p.training}회 · 공식 입상 ${p.podiums}회`;
$('upgrades').innerHTML=E.KEYS.map(k=>`<div class="upgrade"><div class="upgrade-title"><strong>${E.LABELS[k]}</strong><b>LV.${p.levels[k]}</b></div><small>${desc[k]}</small><button data-up="${k}" ${active||p.levels[k]>=100||p.coins<E.price(p.levels,k,p.settings)?'disabled':''}><span>${p.levels[k]>=100?'최고 레벨':'레벨 올리기 +'}</span><span>${p.levels[k]>=100?'MAX':E.price(p.levels,k,p.settings).toLocaleString()+' C'}</span></button></div>`).join('');document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{if(E.buy(p,b.dataset.up)){save();update();}});
$('distance').disabled=!!active;$('strategy').disabled=!!active;$('training').disabled=!!active;$('stadium').disabled=!!active;$('openLab').disabled=!!active;$('retire').disabled=!active;
$('start').textContent=active?(paused?'경기 이어하기 →':'일시 정지 Ⅱ'):`${mode==='training'?'훈련':'공식경기'} 시작 →`;
$('distanceTitle').textContent=distance.toLocaleString()+'m';$('venue').textContent=mode==='training'?'TRAINING GROUND':'OFFICIAL STADIUM';
const est=E.estimate(p.levels,distance,strategy,p.settings);$('readiness').textContent=`${E.STRATEGIES[strategy].desc} · 예상 기본 소모 ${est.baseCost.toFixed(0)} / 체력 ${est.capacity} · 가속 1회 −${est.boostCost.toFixed(1)} (추월 시 추가 소모)`;$('readiness').classList.toggle('warn',est.baseCost>est.capacity);
$('pbTitle').textContent=`${mode==='training'?'훈련':'공식'} · ${distance.toLocaleString()}m`;$('pb').textContent=p.pbs[mode+'-'+distance]?fmt(p.pbs[mode+'-'+distance]):'아직 기록이 없어요';$('recordNote').textContent=`기록 보상 기준: ${E.bands[distance].map(t=>fmt(t)).join(' / ')} 이내. 거리 보상 가중치 ×${p.settings.distanceWeights[distance]}.`;
$('history').innerHTML=p.history.slice(0,5).map(h=>`<p>${h.mode==='training'?'훈련':'공식'} ${h.distance}m · ${fmt(h.time)} · +${h.coins} C</p>`).join('')||'<p>첫 경기를 시작해 보세요.</p>';
document.querySelectorAll('[data-play]').forEach(b=>b.classList.toggle('on',+b.dataset.play===playback));updateLive();}
function updateLive(){const a=race?.racers[0],active=race&&!race.done;const capacity=active||race? a.capacity:E.maxStamina(p.levels,p.settings),energy=active||race?a.stamina:capacity;
$('timer').textContent=fmt(race?.time||0);$('energy').textContent=`${energy.toFixed(0)} / ${capacity.toFixed(0)}`;$('energyBar').style.width=(energy/capacity*100)+'%';$('fatigue').textContent=`후반 피로 ${((a?.fatigue||0)*100).toFixed(1)}%`;$('meters').textContent=(a?.distance||0).toFixed(0)+' m';$('speed').textContent=(a&&a.finish===null?a.speed:0).toFixed(1)+' m/s';
const order=race?E.ranking(race):[];$('rank').textContent=order.length?(order.findIndex(x=>x.id===0)+1)+' / 8':'— / 8';
$('boost').disabled=!active||paused||a.dnf||a.finish!==null||a.boosts===0||race.time<a.cooldownUntil||a.stamina<=E.boostCost(a.levels,race.c);$('boostCount').textContent=`${a?.boosts??E.boosts(p.levels)}회${active&&race.time<a.cooldownUntil?' · '+Math.ceil(a.cooldownUntil-race.time)+'초':''}`;
$('trackLabel').textContent=active?(paused?'PAUSED':a.dnf?'DNF':a.finish!==null?'FINISHED':`${Math.floor(a.distance/400)+1} / ${Math.ceil(distance/400)} LAP`):race?'RACE COMPLETE':'MAKE YOUR MOVE.';$('trackSub').textContent=active?'400m TRACK · '+(a?.boostUntil>race.time?'BOOST ACTIVE':'FIND YOUR PACE'):'400m TRACK · 8 RUNNERS';
$('standings').innerHTML=(order.length?order:Array.from({length:8},(_,id)=>({id,name:id?'상대 선수 '+id:'YOU',distance:0,finish:null}))).map((a,i)=>`<div class="standing ${a.id===0?'me':''}"><span class="position">${i+1}</span><span class="runner-dot" style="background:${colors[a.id]}"></span><span class="who">${a.name}<small>${a.dnf?'체력 소진 · DNF':a.finish!==null?'완주':Math.floor(a.distance)+'m'}</small></span><b>${a.finish!==null?fmt(a.finish):a.id===0?'YOU':'#0'+(a.id+1)}</b></div>`).join('');draw();}
function point(t,offset=0){const radius=90+offset,line=260,per=2*line+2*Math.PI*radius;let s=((t%1+1)%1)*per;if(s<line)return [190+s,260+offset];s-=line;if(s<Math.PI*radius){const a=Math.PI/2-s/radius;return [450+Math.cos(a)*radius,170+Math.sin(a)*radius];}s-=Math.PI*radius;if(s<line)return [450-s,80-offset];s-=line;const a=-Math.PI/2-s/radius;return [190+Math.cos(a)*radius,170+Math.sin(a)*radius];}
function draw(){const cv=$('track');if(!cv)return;const box=cv.getBoundingClientRect(),dpr=devicePixelRatio||1;cv.width=Math.max(1,box.width*dpr);cv.height=Math.max(1,box.height*dpr);const ctx=cv.getContext('2d');ctx.scale(cv.width/640,cv.height/340);ctx.fillStyle='#142124';ctx.fillRect(0,0,640,340);for(let lane=6;lane>=0;lane--){ctx.beginPath();for(let j=0;j<=200;j++){const pt=point(j/200,lane*6);j?ctx.lineTo(...pt):ctx.moveTo(...pt);}ctx.strokeStyle=lane===6?'#47605f':'#345052';ctx.lineWidth=1.2;ctx.stroke();}ctx.fillStyle='#9bad91';ctx.fillRect(184,258,3,40);ctx.font='9px sans-serif';ctx.fillText('FINISH',166,314);const runners=race?.racers||Array.from({length:8},(_,id)=>({id,distance:0,lane:id*.6}));for(const a of [...runners].reverse()){const pos=point((a.distance+400-distance%400)/400,a.lane*6+3);ctx.beginPath();ctx.arc(...pos,a.id===0?9:7,0,Math.PI*2);ctx.fillStyle=a.dnf?'#566161':colors[a.id];ctx.fill();ctx.strokeStyle='#142124';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#132022';ctx.font='bold 8px sans-serif';ctx.textAlign='center';ctx.fillText(a.id+1,pos[0],pos[1]+3);}ctx.textAlign='left';}
function loop(now){const elapsed=last?Math.min((now-last)/1000,.1):0;last=now;if(race&&!race.done&&!paused){accum+=elapsed*playback;p.played+=elapsed;while(accum>=.2&&!race.done){E.step(race,.2);accum-=.2;}if(race.done)finish();else updateLive();if(now-lastSave>3000){save();lastSave=now;}}requestAnimationFrame(loop);}
function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openLab(){if(typeof buildLab==='function')buildLab();}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&race&&!race.done){paused=true;save();update();}});window.addEventListener('beforeunload',save);window.addEventListener('resize',draw);
render();requestAnimationFrame(loop);
